WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_summarize_impact'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '概括影响', 'kp-sl-summarize-impact', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "归纳概括：影响类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心心法：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "影响分为“积极影响（意义）”和“消极影响（危害）”。必须分清！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、分类作答"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "如果题目只说“概括产生的影响”，而材料中既有好的也有坏的，你的答案必须明确分为两大类："}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "积极影响（意义）：促进了...、提高了...、改善了...、实现了...、有利于...。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "消极影响（危害）：阻碍了...、破坏了...、加剧了...、导致了...。"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "千万不要把好的坏的混在一起写成流水账，阅卷老师找不到采分点！"}]}]}$$ AS jsonb), NULL, '概括影响的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "归纳概括", "概括影响"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_summarize_impact", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
